from collections import deque, defaultdict


def cheapest_flight(n, flights, src, dst, k):
    INF = float('inf')
    dist = [INF] * n
    dist[src] = 0
    for _ in range(k + 1):
        new = dist[:]
        for a, b, w in flights:
            if dist[a] + w < new[b]:
                new[b] = dist[a] + w
        dist = new
    return -1 if dist[dst] == INF else dist[dst]
